modes.detail:
// ============ CUTOFF 是什么 ============
//
// 快排递归到"区间很短"的时候，再递归就不划算了 ——
// 因为：
//
//   · 短区间用插入排序本来就很快（近乎有序时接近 O(n)）
//   · 递归有函数调用的开销，短区间下这个开销占比反而大
//   · 短区间的主元选择也没什么意义
//
// 所以惯例是：**区间长度小于某个阈值就直接用插入排序**。
//
// 这个阈值通常取 5~20。这里取 CUTOFF = 3，方便在小数据上看出效果。
//
// 这也是快排比归并快的实际原因之一 —— 归并是老老实实递归到只剩一个元素。
//
// ============ 快排的稳定性 ============
//
// **快排不稳定。**
//
// 原因在划分那一步：元素会被swap到相隔很远的位置，
// 两个相等的元素很可能因此交换了相对顺序。
//
// 所以需要稳定排序时得用归并。

// 元素类型
typedef int ElementType;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 小数组的阈值：区间比它短就改用插入排序
#define CUTOFF 3

// 交换两个元素
void Swap(ElementType *a, ElementType *b)
{
// 临时变量倒手
    ElementType t = *a;
    *a = *b;
    *b = t;
}

// 插入排序（给快排处理小数组用）
// 和 05-01 的写法完全一样，只是范围变成了 A[0..N-1]。
void InsertionSort(ElementType A[], int N)
{
// 循环用
    int i, j;
// 暂存当前元素
    ElementType tmp;

    for (i = 1; i < N; i++)
    {
        tmp = A[i];
        for (j = i; j > 0 && A[j - 1] > tmp; j--)
        {
            A[j] = A[j - 1];
        }
        A[j] = tmp;
    }
}

