{
    int i = Left;
    int j = Right - 1;

    for (;;)
    {
        while (A[++i] < Pivot)
        {
        }

        while (A[--j] > Pivot)
        {
        }

        if (i >= j)
        {
            break;
        }

        Swap(&A[i], &A[j]);
    }

    Swap(&A[i], &A[Right - 1]);

    return i;
}

