#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

typedef int ElementType;

#define OK 1
#define ERROR 0
typedef int Status;

#define CUTOFF 3

void Swap(ElementType *a, ElementType *b)
{
    ElementType t = *a;
    *a = *b;
    *b = t;
}

void InsertionSort(ElementType A[], int N)
{
    int i, j;
    ElementType tmp;

    for (i = 1; i < N; i++)
    {
        tmp = A[i];
        for (j = i; j > 0 && A[j - 1] > tmp; j--)
        {
            A[j] = A[j - 1];
        }
        A[j] = tmp;
    }
}

/* ======== [已给出] 模块 02 Median3 ======== */

ElementType Median3(ElementType A[], int Left, int Right)
{
    int Center = (Left + Right) / 2;

    if (A[Left] > A[Center])
    {
        Swap(&A[Left], &A[Center]);
    }

    if (A[Left] > A[Right])
    {
        Swap(&A[Left], &A[Right]);
    }

    if (A[Center] > A[Right])
    {
        Swap(&A[Center], &A[Right]);
    }

    Swap(&A[Center], &A[Right - 1]);

    return A[Right - 1];
}

/* ======== [已给出] 模块 03 Partition ======== */

int Partition(ElementType A[], int Left, int Right, ElementType Pivot)
{
    int i = Left;
    int j = Right - 1;

    for (;;)
    {
        while (A[++i] < Pivot)
        {
        }

        while (A[--j] > Pivot)
        {
        }

        if (i >= j)
        {
            break;
        }

        Swap(&A[i], &A[j]);
    }

    Swap(&A[i], &A[Right - 1]);

    return i;
}

/* ======== [已给出] 模块 04 QSort ======== */

void QSort(ElementType A[], int Left, int Right)
{
    ElementType Pivot;
    int i;

    if (Right - Left >= CUTOFF)
    {
        Pivot = Median3(A, Left, Right);

        i = Partition(A, Left, Right, Pivot);

        QSort(A, Left, i - 1);

        QSort(A, i + 1, Right);
    }
    else
    {
        InsertionSort(A + Left, Right - Left + 1);
    }
}

/* ======== [已给出] 模块 05 QuickSort ======== */

void QuickSort(ElementType A[], int N)
{
    if (N < 2)
    {
        return;
    }

    QSort(A, 0, N - 1);
}

/* ======== [已给出] 模块 06 PrintArray ======== */

void PrintArray(const ElementType A[], int N)
{
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

int IsSorted(const ElementType A[], int N)
{
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}

