#include <stdio.h>
#include <stdlib.h>


// 元素类型
typedef int ElementType;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 小数组的阈值：区间比它短就改用插入排序
#define CUTOFF 3

// 交换两个元素
void Swap(ElementType *a, ElementType *b)
{
// 临时变量倒手
    ElementType t = *a;
    *a = *b;
    *b = t;
}

// 插入排序（给快排处理小数组用）
void InsertionSort(ElementType A[], int N)
{
// 循环用
    int i, j;
// 暂存当前元素
    ElementType tmp;

    for (i = 1; i < N; i++)
    {
        tmp = A[i];
        for (j = i; j > 0 && A[j - 1] > tmp; j--)
        {
            A[j] = A[j - 1];
        }
        A[j] = tmp;
    }
}


// 取 A[Left]、A[Center]、A[Right] 的中位数作为主元
ElementType Median3(ElementType A[], int Left, int Right)
{
// 中间位置
    int Center = (Left + Right) / 2;

// 第一步：让 A[Left] <= A[Center]
    if (A[Left] > A[Center])
    {
        Swap(&A[Left], &A[Center]);
    }

// 第二步：让 A[Left] <= A[Right]
    if (A[Left] > A[Right])
    {
        Swap(&A[Left], &A[Right]);
    }

// 第三步：让 A[Center] <= A[Right]
    if (A[Center] > A[Right])
    {
        Swap(&A[Center], &A[Right]);
    }

// 把主元（Center 位置上的那个）换到 A[Right - 1]
    Swap(&A[Center], &A[Right - 1]);

// 返回主元的值
    return A[Right - 1];
}


// 划分：返回主元最终所在的位置
int Partition(ElementType A[], int Left, int Right, ElementType Pivot)
{
// 左指针：从 Left+1 开始（A[Left] 是左哨兵，不用动）
    int i = Left;
// 右指针：从 Right-1 开始（主元就在那儿，也不动）
    int j = Right - 1;

// 两头往中间夹
    for (;;)
    {
// 从左往右找第一个 >= 主元的
        while (A[++i] < Pivot)
        {
        }

// 从右往左找第一个 <= 主元的
        while (A[--j] > Pivot)
        {
        }

// 两个指针错开了 → 划分结束
        if (i >= j)
        {
            break;
        }

// 否则交换这两个"站错队"的元素
        Swap(&A[i], &A[j]);
    }

// 把主元换到 i 的位置 —— 从此它永远到位
    Swap(&A[i], &A[Right - 1]);

// 返回主元的位置
    return i;
}


// 对 A[Left..Right] 做快速排序
void QSort(ElementType A[], int Left, int Right)
{
// 主元
    ElementType Pivot;
// 主元最终位置
    int i;

// ① 区间足够长才用快排
    if (Right - Left >= CUTOFF)
    {
// ② 选主元，顺便把边界排好
        Pivot = Median3(A, Left, Right);

// ③ 划分，拿到主元的位置
        i = Partition(A, Left, Right, Pivot);

// ④ 左半边（不含主元）
        QSort(A, Left, i - 1);

// ⑤ 右半边（不含主元）
        QSort(A, i + 1, Right);
    }
// 区间太短 → 插入排序收尾
    else
    {
        InsertionSort(A + Left, Right - Left + 1);
    }
}


void QuickSort(ElementType A[], int N)
{
// 空数组或只有一个元素，天然有序
    if (N < 2)
    {
        return;
    }

// 调用递归主体
    QSort(A, 0, N - 1);
}


// 打印数组
void PrintArray(const ElementType A[], int N)
{
// 循环用
    int i;

    printf("[");
    for (i = 0; i < N; i++)
    {
        printf("%d", A[i]);
        if (i < N - 1)
        {
            printf(", ");
        }
    }
    printf("]");
}

// 检查是否有序
int IsSorted(const ElementType A[], int N)
{
// 循环用
    int i;

    for (i = 0; i + 1 < N; i++)
    {
        if (A[i] > A[i + 1])
        {
            return 0;
        }
    }
    return 1;
}


// 主函数
